long fact(int n)      // 使用循环的函数
{
long  ans;
for (ans = 1; n > 1; n--)
ans *= n;
return  ans;
}
long rfact(int n)      // 使用递归的函数
{
long  ans;
if (n > 0)
ans = n * rfact(n - 1);
else
ans = 1;
return  ans;
}
```

